    h = obs.get('hitch_deg', 0.0)
    if st in ('JACKKNIFED', 'PINNED') or abs(h) > 45:
        return (0.0, 1.0)
    steer = 2.5 * (h + 3.0)
    steer = max(-30.0, min(30.0, steer))
    return (steer, -1.0)

