KP = 2.5
KD = 0.4
VREV = -0.6
state = {'last': None, 'phase': 'rev', 'fwd_until': 0.0}

def control(obs):
    h = obs['hitch_deg']
    t = obs['t']
    st = obs['status']
    dt = obs.get('dt', 0.1) or 0.1
    if state['last'] is None:
        dh = 0.0
    else:
        dh = (h - state['last']) / dt
    state['last'] = h
    if st in ('JACKKNIFED', 'PINNED') and state['phase'] != 'fwd':
        state['phase'] = 'fwd'
        state['fwd_until'] = t + 3.0
    if state['phase'] == 'fwd':
        if t < state['fwd_until']:
            return (0.0, 1.0, 180)
        state['phase'] = 'rev'
    target = -4.0 * max(0.0, 1.0 - t / 12.0)
    e = h - target
    steer = KP * e + KD * dh
    if steer > 40:
        steer = 40.0
    if steer < -40:
        steer = -40.0
    return (steer, VREV, 180)

